PHOTO = {
    "forest": "https://images.unsplash.com/photo-1448375240586-882707db888b?w=700&auto=format&fit=crop",
    "sea": "https://images.unsplash.com/photo-1518837695005-2083093ee35b?w=700&auto=format&fit=crop",
    "night": "https://images.unsplash.com/photo-1470225620780-dba8ba36b745?w=700&auto=format&fit=crop",
    "sky": "https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?w=700&auto=format&fit=crop",
    "city": "https://images.unsplash.com/photo-1519608487953-e999c86e7455?w=700&auto=format&fit=crop",
    "podcast": "https://images.unsplash.com/photo-1478737270239-2f02b77fc618?w=700&auto=format&fit=crop",
}
LINK_ID = 0

def icon(name):
    return f'<iconify-icon icon="material-symbols:{name}" aria-hidden="true"></iconify-icon>'

def link(target, content, cls="", label=""):
    global LINK_ID
    LINK_ID += 1
    return f'<a id="navigate-{target}-{LINK_ID}" href="#{target}" data-route="{target}" class="{cls}" aria-label="{label or html.escape(target)}">{content}</a>'

def ib(name, target="menu", label="更多"):
    return link(target, icon(name), "icon", label)

def image(key, cls="art", alt="封面"):
    return f'<img class="{cls}" src="{html.escape(PHOTO[key])}" alt="{alt}">'

def btn(text, target, kind="", glyph=""):
    return link(target, (icon(glyph) if glyph else "") + text, f"btn {kind}", text)

def row(title="夏夜晚风", subtitle="伍佰 & China Blue · 爱情的尽头", key="forest", target="player", index=None, trailing="more-vert", active=False):
    start = f'<span class="index">{index}</span>' if index else image(key)
    end = ib(trailing, "track-menu", "歌曲更多操作") if trailing else ""
    return f'<div class="row {"queue-active" if active else ""}">{start}{link(target, f"<h3>{title}</h3><p>{subtitle}</p>", "info", title)}{end}</div>'

def card(name, desc, key, target="playlist"):
    return link(target, f'<div class="cover">{image(key,"","歌单封面")}<span class="badge">{icon("headphones")}12.8万</span></div><h3>{name}</h3><p>{desc}</p>', "card", name)

def section(title, target="", action="查看全部"):
    return f'<div class="section"><h2>{title}</h2>{link(target, action+icon("chevron-right"), "", action) if target else ""}</div>'

def bar(title="", back=True, right="settings", name=""):
    left = ib("arrow-back", "discover", "返回") if back else f'<span class="name">{name or "PETRICHOR"}</span>'
    middle = f'<span class="title">{title}</span>' if title else ""
    return f'<header class="bar">{left}{middle}{ib("more-vert" if back else "person-outline",right,"更多" if back else "我的账号")}</header>'

def mini():
    return f'<div class="mini">{image("forest")}{link("player","<h3>夏夜晚风</h3><p>伍佰 & China Blue</p>","info","打开正在播放")}{ib("play-arrow","player","播放或暂停")}{ib("skip-next","queue","下一首")}<div class="progress"></div></div>'

def nav(active):
    return '<nav class="nav">' + ''.join(link(route, f'<span class="pill">{icon(glyph)}</span><span>{title}</span>', 'active' if route==active else '', title) for route,title,glyph in [('discover','发现','explore-outline'),('search','搜索','search'),('podcasts','播客','podcasts'),('library','我的','library-music-outline')]) + '</nav>'

STATUS = '<div class="status"><span>9:41</span><span class="icons">'+icon("signal-cellular-alt")+icon("wifi")+icon("battery-full")+'</span></div>'
HOME = '<div class="homebar"></div>'

def screen(body, title="", tab="", player=True, back=True, right="settings"):
    return STATUS + bar(title,back,right) + '<main class="main"><div class="pad">' + body + '</div></main>' + (mini() if player else '') + (nav(tab) if tab else '') + HOME

def field(label, placeholder, extra="", value=""):
    return f'<div class="field"><label>{label}</label><input aria-label="{label}" placeholder="{placeholder}" value="{value}">{extra}</div>'

def program(name, host="木槿花", key="sky", duration="04:11"):
    parent = link("podcast",icon("podcasts")+f'<span>所属播客 · {host}</span>查看'+icon("chevron-right"),"parent","查看所属播客")
    return f'<article class="program"><div class="row">{image(key)}{link("player", f"<h3>{name}</h3><p>歌曲翻唱 · {duration}</p>","info",name)}{ib("play-arrow","player","播放节目")}</div>{parent}</article>'

SCREENS = {}
SCREENS["discover"] = ("发现", screen('<div class="heading"><h1>听见，新的喜欢。</h1><p class="body muted">午后好，留一点时间给音乐。</p></div>'+link("search",icon("search")+'<span>搜索歌曲、播客和节目</span>',"search","搜索")+'<div class="shortcuts">'+''.join(link(t,f'<span class="bubble">{icon(g)}</span><span>{n}</span>',"shortcut",n) for n,g,t in [('每日推荐','today','daily'),('私人 FM','radio','fm'),('排行榜','bar-chart','charts')])+'</div>'+section("为你而选","playlists")+'<div class="cards">'+card("雨后森林，慢慢呼吸","自然与器乐 · 48首","forest")+card("海风吹过的夏天","华语与独立 · 36首","sea")+card("夜色里的一点浪漫","城市夜行 · 52首","city")+card("把心事交给远山","安静片刻 · 24首","sky")+'</div>'+section("让声音陪你","podcasts")+row("日落之后，我们聊聊","声波漫游 · 最新更新","podcast","podcast",trailing="chevron-right"), tab="discover",back=False))
