SCRIPT = r"""
const palettes={rose:['#B91C42','#FFD9E2','#3F0016'],teal:['#006B5E','#9DF2DF','#00201A'],violet:['#65558F','#E9DDFF','#211047']};
function setTheme(palette,dark){const c=palettes[palette]||palettes.rose,r=document.documentElement.style;r.setProperty('--p',dark?c[1]:c[0]);r.setProperty('--onp',dark?c[2]:'#fff');r.setProperty('--pc',dark?c[0]:c[1]);r.setProperty('--onpc',dark?'#fff':c[2]);const t=dark?['#181216','#241E22','#30292D','#F0E0E6','#CDBEC4','#504348']:['#FFFBFC','#F7ECEF','#F0E3E7','#23191C','#76666C','#DAC2CA'];['--s','--sc','--high','--ink','--muted','--line'].forEach((k,i)=>r.setProperty(k,t[i]));if(palette==='teal'){r.setProperty('--s',dark?'#101513':'#F4FBF7');r.setProperty('--sc',dark?'#1D2521':'#E7F1EB');r.setProperty('--high',dark?'#2A332F':'#DBE6DF');}if(palette==='violet'){r.setProperty('--s',dark?'#151218':'#FFFBFF');r.setProperty('--sc',dark?'#231F28':'#F2ECF6');} }
addEventListener('message',e=>{if(e.data&&e.data.type==='petrichor-theme')setTheme(e.data.palette,e.data.dark)});
document.querySelectorAll('[data-route]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();let route=a.dataset.route;if(window.parent!==window)window.parent.postMessage({type:'petrichor-route',route},'*');else location.href=route+'.html'+location.search;}));
document.querySelectorAll('.chips').forEach(p=>{const a=p.querySelector('.active');if(a)p.scrollLeft=Math.max(0,a.offsetLeft+a.offsetWidth-p.clientWidth+8)});
setTimeout(()=>document.querySelectorAll('.chips').forEach(p=>{const a=p.querySelector('.active');if(a===p.lastElementChild)p.scrollLeft=p.scrollWidth;}),700);
const params=new URLSearchParams(location.search);setTheme(params.get('palette')||'rose',params.get('dark')==='true');
"""

META=[]
for slug,(title,content) in SCREENS.items():
    doc=f'''<!DOCTYPE html><html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Petrichor · {title}</title><script src="https://cdn.tailwindcss.com"></script><script src="https://code.iconify.design/iconify-icon/1.0.7/iconify-icon.min.js"></script><style>{CSS}</style></head><body><div class="app relative flex flex-col">{content}</div><script>{SCRIPT}</script></body></html>'''
    (OUT/f'{slug}.html').write_text(doc,encoding='utf-8')
    META.append({'slug':slug,'title':title,'file':f'design/android/{slug}.html'})
(OUT/'screens.json').write_text(json.dumps(META,ensure_ascii=False,indent=2),encoding='utf-8')
print(f'Created {len(META)} MD3 screen drafts in {OUT}')

GALLERY_CSS=r"""
*{box-sizing:border-box}body{margin:0;background:#F4F2F4;font:14px system-ui,sans-serif;color:#292429}button,select{font:inherit;cursor:pointer}header{position:sticky;top:0;background:#FFFCFEED;backdrop-filter:blur(12px);border-bottom:1px solid #E4DCE1;z-index:5;display:flex;align-items:center;gap:14px;padding:18px 28px;flex-wrap:wrap}h1{font-size:18px;margin:0}header p{margin:4px 0 0;font-size:12px;color:#776A73}.spacer{flex:1}.controls{display:flex;gap:10px;align-items:center}select,button{padding:9px 12px;border:1px solid #D6C6CE;border-radius:18px;background:#fff;color:#47313C}.toggle.active{background:#34242E;color:white}.tabs{display:flex;gap:8px;flex-wrap:wrap;padding:24px 28px 0}.tabs button{border:0;background:#E9E1E6}.tabs button.active{background:#FFD9E2;color:#700023}.grid{padding:28px;display:grid;grid-template-columns:repeat(auto-fit,minmax(370px,1fr));gap:30px;justify-items:center}.frame-wrap{width:372px;max-width:100%}.caption{display:flex;align-items:center;justify-content:space-between;margin-bottom:10px}.caption h2{font-size:14px;font-weight:500;margin:0}.caption a{color:#9B2544;text-decoration:none;font-size:12px}.frame{width:372px;height:806px;background:white;border:1px solid #D8CFD5;border-radius:24px;overflow:hidden;box-shadow:0 8px 32px #35232E09}.frame iframe{border:0;width:412px;height:892px;transform:scale(.9);transform-origin:0 0;display:block}.note{padding:10px 28px;color:#83717D;font-size:12px;line-height:1.8}.focus .grid{display:block}.focus .frame-wrap{margin:auto}.focus .frame-wrap:not(.chosen){display:none}.focus .frame{width:412px;height:892px}.focus .frame iframe{transform:none}.focus .frame-wrap{width:412px}footer{padding:8px 28px 30px;color:#83717D;font-size:12px}
"""
groups={"全部":list(SCREENS),"主要页面":["discover","search","podcasts","library"],"播放":["player","lyrics","queue","fm","sleep"],"账号与歌单":["login","qr-login","library-guest","playlist","create-playlist","choose-playlist","track-menu","selection"],"内容与离线":["podcast","artist","album","daily","charts","playlists","liked","subscribed","saved","recent","downloads","local"],"状态与设置":["settings","search-songs","empty-search","network-error","comments","replies"]}
gallery='''<!DOCTYPE html><html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Petrichor Android · MD3 全页面设计</title><style>'''+GALLERY_CSS+'''</style></head><body><header><div><h1>Petrichor / Android · Material Design 3</h1><p>完整页面设计 · 动态主题预览 · 贴边播放栏</p></div><span class="spacer"></span><div class="controls"><select id="palette" aria-label="动态配色预览"><option value="rose">玫红 · 默认</option><option value="teal">青绿 · 壁纸示例</option><option value="violet">紫罗兰 · 壁纸示例</option></select><button id="dark" class="toggle">深色模式</button><button id="all">全部页面</button></div></header><div class="tabs" id="tabs"></div><p class="note">这是设计原型，曲目、封面和账号信息均为示例。动态配色选项模拟不同壁纸；Android 实现会读取系统调色板。点击屏幕中的入口可在当前预览中切换页面，播放和账号操作尚未连接。</p><main class="grid" id="grid"></main><footer>原生 MAUI 页面将按此设计实现；手机登录、歌单写入仍需真实账号验收。</footer><script>'''+f'const screens={json.dumps(META,ensure_ascii=False)},groups={json.dumps(groups,ensure_ascii=False)};'+r'''
let currentGroup='主要页面',dark=false;const grid=document.getElementById('grid'),palette=document.getElementById('palette');function theme(){document.querySelectorAll('iframe').forEach(f=>f.contentWindow.postMessage({type:'petrichor-theme',palette:palette.value,dark},'*'));}function show(group){currentGroup=group;grid.innerHTML=groups[group].map(slug=>{const s=screens.find(x=>x.slug===slug);return `<section class="frame-wrap" id="wrap-${slug}"><div class="caption"><h2>${s.title}</h2><a href="${slug}.html" target="_blank">单独查看 ↗</a></div><div class="frame"><iframe title="${s.title}" src="${slug}.html?palette=${palette.value}&dark=${dark}" loading="lazy"></iframe></div></section>`}).join('');document.querySelectorAll('.tabs button').forEach(b=>b.classList.toggle('active',b.textContent===group));document.querySelectorAll('iframe').forEach(f=>f.addEventListener('load',theme));}Object.keys(groups).forEach(g=>{const b=document.createElement('button');b.textContent=g;b.onclick=()=>{document.body.classList.remove('focus');show(g)};document.getElementById('tabs').append(b)});palette.onchange=theme;document.getElementById('dark').onclick=()=>{dark=!dark;document.getElementById('dark').classList.toggle('active',dark);theme()};document.getElementById('all').onclick=()=>{document.body.classList.remove('focus');show('全部')};addEventListener('message',e=>{if(e.data?.type==='petrichor-route'){const s=screens.find(s=>s.slug===e.data.route);if(!s)return;const f=[...document.querySelectorAll('iframe')].find(f=>f.contentWindow===e.source);if(f){f.src=s.slug+'.html?palette='+palette.value+'&dark='+dark;f.title=s.title;f.closest('section').querySelector('h2').textContent=s.title;f.closest('section').querySelector('a').href=s.slug+'.html';}}if(e.data?.petrichorPalette){palette.value=palette.value==='teal'?'rose':'teal';theme()}});const initial=new URLSearchParams(location.search);if(initial.get('screens'))groups['审核']=initial.get('screens').split(',');dark=initial.get('dark')==='true';palette.value=initial.get('palette')||'rose';show(initial.get('screens')?'审核':(initial.get('group')||currentGroup));
</script></body></html>'''
(OUT/'index.html').write_text(gallery,encoding='utf-8')
